import sys

# Released openpilot updaters embed a UI that still uses raygui. New openpilot
# and the standalone AGNOS apps use the current raylib package instead.
if sys.argv and sys.argv[0].endswith('/updater'):
  import zipfile

  if zipfile.is_zipfile(sys.argv[0]):
    with zipfile.ZipFile(sys.argv[0]) as updater:
      label = 'openpilot/system/ui/widgets/label.py'
      if label in updater.namelist() and b'rl.GuiTextAlignment' in updater.read(label):
        sys.path.insert(0, '/usr/local/legacy-raylib')
